def transform(grid):
    out = [[0] * 10 for _ in range(10)]
    seen = set()
    components = []

    for r in range(10):
        for c in range(10):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < 10 and 0 <= nx < 10 and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    colors = {color for color, _ in components}
    left_color = min(colors, key=lambda col: min(c for color, cells in components if color == col for _, c in cells))

    for color in colors:
        group = [(cells) for col, cells in components if col == color]
        group.sort(key=len)  # smaller shape sits above the larger shape
        xbase = 0 if color == left_color else 5
        for i, cells in enumerate(group):
            minr = min(r for r, _ in cells)
            maxr = max(r for r, _ in cells)
            minc = min(c for _, c in cells)
            bottom = 5 if i == 0 else 9
            for r, c in cells:
                out[bottom - (maxr - r)][xbase + (c - minc)] = color

    return out
